document.body.insertAdjacentHTML('beforeend',`<dialog class="automation-dialog" id="letterCompose"><form id="letterForm"><div class="dialog-head"><h2 id="letterFormTitle">ثبت و ارجاع جدید</h2><button type="button" class="close" id="cancelComposeX">×</button></div><p class="hint" id="letterOrigin"></p><label>موضوع<input name="subject" required maxlength="180" placeholder="مثلاً بررسی و اعلام نظر درباره نقشه اجرایی"></label><label>شرح کار / دستور ارجاع<textarea name="body" required maxlength="10000" rows="5" placeholder="اقدام مورد انتظار و توضیحات را بنویسید"></textarea></label><fieldset class="recipient-fieldset"><legend>گیرنده‌ها</legend><div id="letterRecipients" class="recipient-grid"></div></fieldset><div class="fields"><label>مهلت پاسخ / انجام<input name="due" type="date"></label><label>تسک مرتبط (اختیاری)<select name="taskId" id="letterTask"></select></label></div><label>پیوست‌ها<input name="files" id="letterFiles" type="file" multiple></label><p class="hint">حداکثر ۱۰ فایل جدید، هر فایل ۲۰ مگابایت و مجموعاً ۵۰ مگابایت. فایل‌ها در حافظه همین مرورگر ذخیره می‌شوند.</p><div id="inheritedFiles"></div><div id="letterFileList" class="hint"></div><div class="form-footer"><button type="button" class="secondary" id="cancelCompose">انصراف</button><button class="primary" id="sendLetter">ثبت و ارجاع در نمونه</button></div></form></dialog><dialog class="automation-dialog" id="letterDetail"><div id="letterDetailBody"></div></dialog>`);
$('#cancelCompose').onclick=$('#cancelComposeX').onclick=()=>{if(!automationBusy)$('#letterCompose').close()};$('#letterFiles').onchange=e=>{$('#letterFileList').textContent=Array.from(e.target.files).map(f=>f.name+' ('+formatBytes(f.size)+')').join('، ')};$('#letterForm').onsubmit=async e=>{e.preventDefault();if(automationBusy)return;if(!members[me()]?.active)return;const form=new FormData(e.target),recipients=form.getAll('recipients').map(Number),newFiles=Array.from($('#letterFiles').files),subject=String(form.get('subject')).trim(),body=String(form.get('body')).trim();if(!subject||!body)return;if(!recipients.length)return toast('حداقل یک گیرنده انتخاب کنید');if(recipients.some(i=>!members[i]?.active||members[i]?.legacy||i===me()))return toast('گیرنده معتبر نیست');if(newFiles.length>10||newFiles.some(f=>f.size>20*1048576)||newFiles.reduce((a,f)=>a+f.size,0)>50*1048576)return toast('تعداد یا حجم پیوست‌ها بیشتر از حد مجاز است');automationBusy=true;$('#sendLetter').disabled=true;$('#sendLetter').textContent='در حال ثبت…';try{const letter=await storeLetter({subject,body,recipients,due:String(form.get('due')||''),taskId:String(form.get('taskId')||'')},newFiles,forwardSource);$('#letterCompose').close();forwardSource=null;letterBox='outbox';view='automation';render();toast('ارجاع '+letter.refNo+' در نمونه ثبت شد')}catch{toast('ثبت کامل نشد؛ فضای ذخیره مرورگر را بررسی و دوباره تلاش کنید.')}finally{automationBusy=false;$('#sendLetter').disabled=false;$('#sendLetter').textContent='ثبت و ارجاع در نمونه'}};
